int fd = 5; // Open file descriptor
uid_t new_uid = 1001;
gid_t new_gid = 200;
int status;

// Change ownership of file referenced by fd
status = fchown32(fd, new_uid, new_gid);

// Example: Change group only, leave owner unchanged (-1)
status = fchown32(fd, (uid_t)-1, 501);

// Example: Change owner only, leave group unchanged (-1)
status = fchown32(fd, 1002, (gid_t)-1);

if (status == -1) {
    // Check errno for EPERM, EBADF, etc.
}
